function App(){const slug=new URLSearchParams(location.search).get("loja");const[user,setUser]=useState(undefined);useEffect(()=>{startAnalytics();if(slug){setUser(null);return}return onAuthStateChanged(auth,setUser)},[slug]);if(slug)return <PublicMenu slug={slug}/>;if(user===undefined)return <div className="loading">Carregando...</div>;if(!user)return <Login/>;return <TenantGate user={user}/>}
function PublicMenu({slug}){const[state,setState]=useState({loading:true,error:"",settings:null,categories:[],products:[],deliveryAreas:[],deliveryMode:"NEIGHBORHOOD"}),[selected,setSelected]=useState(null),[choices,setChoices]=useState({}),[cart,setCart]=useState([]),[cartOpen,setCartOpen]=useState(false),[checkout,setCheckout]=useState(false),[checkoutData,setCheckoutData]=useState({channel:"DELIVERY",name:"",phone:"",cep:"",address:"",number:"",complement:"",neighborhood:"",city:"",state:"",latitude:null,longitude:null,distanceKm:null,table:"",paymentMethod:"PIX"}),[sending,setSending]=useState(false),[orderDone,setOrderDone]=useState(null),[checkoutError,setCheckoutError]=useState("");useEffect(()=>{(async()=>{try{const map=await getDoc(doc(db,"restaurantSlugs",slug));if(!map.exists())throw new Error("notfound");const restaurantId=map.data().restaurantId;const settings=await getDoc(doc(db,"restaurants",restaurantId,"settings","public"));if(!settings.exists()||settings.data().published!==true)throw new Error("closed");const[c,p,a,deliveryCfg]=await Promise.all([getDocs(collection(db,"restaurants",restaurantId,"categories")),getDocs(collection(db,"restaurants",restaurantId,"products")),getDocs(collection(db,"restaurants",restaurantId,"deliveryAreas")),getDoc(doc(db,"restaurants",restaurantId,"settings","delivery"))]);setState({loading:false,error:"",settings:{...settings.data(),restaurantId},categories:c.docs.map(x=>({id:x.id,...x.data()})).filter(x=>x.active!==false).sort((a,b)=>(a.order||0)-(b.order||0)),products:p.docs.map(x=>({id:x.id,...x.data()})).filter(x=>x.active!==false),deliveryMode:deliveryCfg.exists()?deliveryCfg.data().mode||"NEIGHBORHOOD":"NEIGHBORHOOD",deliveryAreas:a.docs.map(x=>({id:x.id,...x.data()})).filter(x=>x.active!==false)})}catch(e){setState(v=>({...v,loading:false,error:e.message==="notfound"?"Cardápio não encontrado.":"Este cardápio ainda não está disponível."}))}})()},[slug]);if(state.loading)return <div className="publicLoading">Carregando cardápio...</div>;if(state.error)return <div className="publicLoading"><Store/><h2>{state.error}</h2></div>;const money=v=>(Number(v||0)/100).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});function openProduct(p){setSelected(p);setChoices({})}function toggleChoice(gi,oi,g){setChoices(v=>{const cur=v[gi]||[];if((g.max||1)===1)return{...v,[gi]:[oi]};return{...v,[gi]:cur.includes(oi)?cur.filter(x=>x!==oi):[...cur,oi].slice(0,g.max||99)}})}function changeQty(key,delta){setCart(v=>v.map(x=>x.key===key?{...x,qty:Math.max(0,x.qty+delta)}:x).filter(x=>x.qty>0))}function removeCart(key){setCart(v=>v.filter(x=>x.key!==key))}function startCheckout(){setCartOpen(false);setCheckout(true);setCheckoutError("")}async function lookupCep(){const cep=checkoutData.cep.replace(/\D/g,"");if(cep.length!==8){setCheckoutError("Digite um CEP com 8 números.");return}setCheckoutError("Buscando endereço...");try{const r=await fetch("/api/lookup-cep?cep="+cep),d=await r.json();if(!r.ok)throw new Error();setCheckoutData(v=>({...v,cep:d.cep,address:d.address,neighborhood:d.neighborhood,city:d.city,state:d.state,latitude:null,longitude:null,distanceKm:null}));setCheckoutError("")}catch{setCheckoutError("CEP não encontrado. Você pode preencher o endereço manualmente.")}}function useMyLocation(){if(!navigator.geolocation){setCheckoutError("Localização não disponível neste aparelho.");return}setCheckoutError("Buscando sua localização e endereço...");navigator.geolocation.getCurrentPosition(async p=>{const latitude=p.coords.latitude,longitude=p.coords.longitude;setCheckoutData(v=>({...v,latitude,longitude}));try{const r=await fetch("/api/delivery-route",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"reverse",latitude,longitude})}),d=await r.json();if(!r.ok)throw new Error(d.error);setCheckoutData(v=>({...v,latitude,longitude,address:d.address||v.address,number:d.number||v.number,neighborhood:d.neighborhood||v.neighborhood,city:d.city||v.city,state:(d.state||v.state||"").replace("BR-",""),cep:d.cep||v.cep}));setCheckoutError(d.number?"Endereço encontrado. Confira rua e número antes de continuar.":"Endereço aproximado encontrado. Confirme a rua e digite o número da residência.")}catch{setCheckoutError("Localização capturada, mas não conseguimos preencher o endereço. Use o CEP ou preencha manualmente.")}},()=>setCheckoutError("Não foi possível acessar sua localização. Use o CEP ou preencha manualmente."),{enableHighAccuracy:true,timeout:12000,maximumAge:60000})}function neighborhoodKey(v){return String(v||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9 ]/g," ").replace(/\s+/g," ").trim()}function selectedDeliveryArea(){const key=neighborhoodKey(checkoutData.neighborhood);return key?state.deliveryAreas.find(a=>neighborhoodKey(a.neighborhoodKey||a.neighborhood)===key):null}async function finishOrder(e){e.preventDefault();setCheckoutError("");if(checkoutData.name.trim().length<2||checkoutData.phone.replace(/\D/g,"").length<10){setCheckoutError("Informe nome e WhatsApp corretamente.");return}if(checkoutData.channel==="DELIVERY"){if(!checkoutData.address.trim()||!checkoutData.number.trim()||!checkoutData.neighborhood.trim()){setCheckoutError("Busque o CEP e confirme endereço, número e bairro.");return}if(state.deliveryMode!=="DISTANCE"){const area=selectedDeliveryArea();if(!area){setCheckoutError("Este estabelecimento não entrega no bairro "+checkoutData.neighborhood+".");return}if(total<Number(area.minimumOrderCents||0)){setCheckoutError("Pedido mínimo para "+area.neighborhood+": "+money(area.minimumOrderCents)+".");return}}}if(checkoutData.channel==="TABLE"&&!checkoutData.table.trim()){setCheckoutError("Informe a mesa ou comanda.");return}setSending(true);try{const r=await fetch("/api/create-order",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({slug,channel:checkoutData.channel,paymentMethod:checkoutData.paymentMethod,customer:{name:checkoutData.name,phone:checkoutData.phone},delivery:checkoutData.channel==="DELIVERY"?{cep:checkoutData.cep,address:checkoutData.address,number:checkoutData.number,complement:checkoutData.complement,neighborhood:checkoutData.neighborhood,city:checkoutData.city,state:checkoutData.state}:null,table:checkoutData.channel==="TABLE"?checkoutData.table:null,items:cart.map(x=>({productId:x.productId,qty:x.qty,options:x.options}))})});const data=await r.json();if(!r.ok){const err=new Error(data.error||"order_error");err.details=data;throw err}setOrderDone(data);setCart([]);setCheckout(false)}catch(e){const msg=e?.message||"";setCheckoutError(msg==="outside_delivery_distance"?"Endereço fora da distância atendida pelo restaurante.":msg==="firebase_admin_not_configured"?"O servidor de pedidos está sem a configuração do Firebase. Avise o estabelecimento.":msg==="origin_address_incomplete"?"O restaurante precisa completar o endereço de origem para calcular a entrega.":msg==="route_not_found"||msg==="address_not_found"||msg==="geocoder_unavailable"||msg==="routing_unavailable"?"Não foi possível calcular a rota com segurança. Confira o endereço e tente novamente.":msg==="outside_delivery_area"?"Este estabelecimento não entrega neste bairro.":msg==="neighborhood_required"?"Não conseguimos identificar o bairro. Busque novamente pelo CEP.":msg==="minimum_order"?`O pedido mínimo para este bairro é ${money(e?.details?.minimumOrderCents||0)}.`:msg==="order_write_failed"?`A entrega foi validada, mas houve erro ao gravar o pedido. Código: ${e?.details?.firestoreCode||"unknown"}.`:`Não foi possível enviar o pedido. Diagnóstico: ${msg||"erro_desconhecido"}.`)}finally{setSending(false)}}function addCart(){const groups=selected.optionGroups||[];if(groups.some((g,i)=>g.required&&!(choices[i]?.length))){alert("Escolha as opções obrigatórias.");return}let extra=0;const picked=[];groups.forEach((g,i)=>(choices[i]||[]).forEach(oi=>{const o=g.options?.[oi];if(o){extra+=Number(o.priceCents||0);picked.push({group:g.name,name:o.name,priceCents:o.priceCents||0})}}));setCart(v=>[...v,{key:Date.now(),productId:selected.id,name:selected.name,unitPriceCents:Number(selected.priceCents||0)+extra,options:picked,qty:1}]);setSelected(null)}const total=cart.reduce((a,x)=>a+x.unitPriceCents*x.qty,0);return <div className="publicMenu"><section className="publicHero"><div className="publicLogo"><Store/></div><div><small>CARDÁPIO DIGITAL</small><h1>{state.settings.name||"Cardápio"}</h1><p>{state.settings.openingHours||"Faça seu pedido online"}</p>{state.settings.address&&<span><MapPin/> {state.settings.address}</span>}</div></section><nav className="categoryNav">{state.categories.map(c=><a key={c.id} href={"#cat-"+c.id}>{c.name}</a>)}</nav><main className="publicContent">{state.categories.map(c=>{const list=state.products.filter(p=>p.categoryId===c.id);return list.length?<section className="publicCategory" id={"cat-"+c.id} key={c.id}><h2>{c.name}</h2><div className="publicProducts">{list.map(p=><button className="publicProduct" key={p.id} onClick={()=>openProduct(p)}><div className="publicProductText"><b>{p.name}</b><p>{p.description||"Toque para ver detalhes"}</p><strong>{money(p.priceCents)}</strong>{p.optionGroups?.length?<small>Personalizável</small>:null}</div>{p.imageUrl?<img src={p.imageUrl} alt={p.name}/>:<div className="publicNoImage"><Package/></div>}</button>)}</div></section>:null})}</main>{cart.length>0&&<button className="cartBar" onClick={()=>setCartOpen(true)}><span><ShoppingCart/> {cart.reduce((a,x)=>a+x.qty,0)} item(ns)</span><b>{money(total)}</b></button>}{cartOpen&&<div className="cartBackdrop" onClick={()=>setCartOpen(false)}><section className="cartDrawer" onClick={e=>e.stopPropagation()}><div className="cartHead"><div><small>SEU PEDIDO</small><h2>Carrinho</h2></div><button onClick={()=>setCartOpen(false)}><X/></button></div><div className="cartItems">{cart.length===0?<div className="cartEmpty"><ShoppingCart/><b>Seu carrinho está vazio</b><span>Adicione produtos para continuar.</span></div>:cart.map(item=><article className="cartItem" key={item.key}><div className="cartItemTop"><div><b>{item.name}</b>{item.options?.map((o,i)=><small key={i}>{o.group}: {o.name}{o.priceCents>0?` (+ ${money(o.priceCents)})`:""}</small>)}</div><strong>{money(item.unitPriceCents*item.qty)}</strong></div><div className="cartItemBottom"><button className="removeItem" onClick={()=>removeCart(item.key)}>Remover</button><div className="qtyControl"><button onClick={()=>changeQty(item.key,-1)}><Minus/></button><b>{item.qty}</b><button onClick={()=>changeQty(item.key,1)}><Plus/></button></div></div></article>)}</div>{cart.length>0&&<div className="cartSummary"><div><span>Subtotal</span><b>{money(total)}</b></div><div className="cartTotal"><span>Total</span><strong>{money(total)}</strong></div><button className="checkoutButton" onClick={startCheckout}>Continuar pedido <ChevronRight/></button><small>Taxa de entrega e forma de pagamento serão definidas na próxima etapa.</small></div>}</section></div>}{checkout&&<div className="checkoutBackdrop"><form className="checkoutSheet" onSubmit={finishOrder}><div className="cartHead"><div><small>FINALIZAR</small><h2>Como deseja receber?</h2></div><button type="button" onClick={()=>setCheckout(false)}><X/></button></div><div className="checkoutBody"><div className="channelChoices">{[["DELIVERY","Delivery",Truck],["PICKUP","Retirada",ShoppingBag],["TABLE","Mesa",Utensils]].map(([v,label,Icon])=><button type="button" key={v} className={checkoutData.channel===v?"active":""} onClick={()=>setCheckoutData({...checkoutData,channel:v})}><Icon/><span>{label}</span></button>)}</div><label>Seu nome<input value={checkoutData.name} onChange={e=>setCheckoutData({...checkoutData,name:e.target.value})} placeholder="Nome" required/></label><label>WhatsApp<input inputMode="tel" value={checkoutData.phone} onChange={e=>setCheckoutData({...checkoutData,phone:e.target.value})} placeholder="(19) 99999-9999" required/></label>{checkoutData.channel==="DELIVERY"&&<><div className="addressFinder"><button type="button" className="locationButton" onClick={useMyLocation}><MapPin/> Usar minha localização</button><div className="cepSearch"><input value={checkoutData.cep} onChange={e=>setCheckoutData({...checkoutData,cep:e.target.value,latitude:null,longitude:null,distanceKm:null})} inputMode="numeric" placeholder="Digite seu CEP"/><button type="button" onClick={lookupCep}>Buscar CEP</button></div>{checkoutData.latitude&&<small className="locationOk">Localização capturada. Confirme o endereço abaixo.</small>}</div><label>Rua / Avenida<input value={checkoutData.address} onChange={e=>setCheckoutData({...checkoutData,address:e.target.value,latitude:null,longitude:null,distanceKm:null})} placeholder="Confirme a rua" required/></label><div className="checkoutTwo"><label>Número<input value={checkoutData.number} onChange={e=>setCheckoutData({...checkoutData,number:e.target.value,latitude:null,longitude:null,distanceKm:null})} placeholder="Número" required/></label><label>Complemento<input value={checkoutData.complement} onChange={e=>setCheckoutData({...checkoutData,complement:e.target.value})} placeholder="Apto, casa..."/></label></div><label>Bairro<input value={checkoutData.neighborhood} onChange={e=>setCheckoutData({...checkoutData,neighborhood:e.target.value,latitude:null,longitude:null,distanceKm:null})} placeholder="Bairro" required/></label><div className="checkoutTwo"><label>Cidade<input value={checkoutData.city} onChange={e=>setCheckoutData({...checkoutData,city:e.target.value})}/></label><label>UF<input value={checkoutData.state} onChange={e=>setCheckoutData({...checkoutData,state:e.target.value})} maxLength="2"/></label></div><div className="routePreview">{state.deliveryMode==="DISTANCE"?<><Truck/><div><b>Taxa calculada pela distância da rota</b><span>O valor será confirmado pelo restaurante ao enviar o pedido, após validar seu endereço.</span></div></>:checkoutData.neighborhood?(selectedDeliveryArea()?<><Truck/><div><b>Entrega para {selectedDeliveryArea().neighborhood}: {money(selectedDeliveryArea().feeCents)}</b><span>{selectedDeliveryArea().estimatedMinutes?` • previsão ${selectedDeliveryArea().estimatedMinutes} min`:""}{selectedDeliveryArea().minimumOrderCents?` • mínimo ${money(selectedDeliveryArea().minimumOrderCents)}`:""}</span></div></>:<><Truck/><b>Este estabelecimento não entrega neste bairro.</b></>):<><Truck/><span>Digite o CEP para verificar a taxa do seu bairro.</span></>}</div><div className="confirmAddress"><b>Confira antes de pedir</b><span>O GPS pode indicar uma rua próxima ou a rua de trás. Confirme principalmente a rua e o número.</span></div></>}{checkoutData.channel==="TABLE"&&<label>Mesa ou comanda<input value={checkoutData.table} onChange={e=>setCheckoutData({...checkoutData,table:e.target.value})} placeholder="Ex.: Mesa 12" required/></label>}<div className="paymentChoices"><b>Forma de pagamento</b>{[["PIX","PIX"],["CASH","Dinheiro"],["CARD_ON_DELIVERY","Cartão"]].map(([v,label])=><label key={v}><input type="radio" checked={checkoutData.paymentMethod===v} onChange={()=>setCheckoutData({...checkoutData,paymentMethod:v})}/><span>{label}</span></label>)}</div>{checkoutError&&<div className="checkoutError">{checkoutError}</div>}</div><div className="checkoutFooter"><div><span>Total dos produtos</span><strong>{money(total)}</strong></div><button className="checkoutButton" disabled={sending}>{sending?"Enviando...":"Confirmar pedido"} <ChevronRight/></button><small>O valor final é validado pelo estabelecimento.</small></div></form></div>}{orderDone&&<div className="checkoutBackdrop"><div className="orderSuccess"><div className="successIcon"><ShoppingBag/></div><small>PEDIDO RECEBIDO</small><h2>Pedido #{orderDone.number}</h2><p>Seu pedido foi enviado para {state.settings.name}.</p><strong>{money(orderDone.totalCents)}</strong>{orderDone.paymentMethod==="PIX"&&<div className="pixPending">PIX selecionado. O pagamento online será disponibilizado quando a conta Mercado Pago do estabelecimento estiver conectada.</div>}<button className="checkoutButton" onClick={()=>setOrderDone(null)}>Voltar ao cardápio</button></div></div>}{selected&&<div className="productModalBackdrop" onClick={()=>setSelected(null)}><div className="productModal" onClick={e=>e.stopPropagation()}><button className="modalClose" onClick={()=>setSelected(null)}><X/></button>{selected.imageUrl&&<img className="modalImage" src={selected.imageUrl} alt={selected.name}/>}<h2>{selected.name}</h2><p>{selected.description}</p><strong className="modalPrice">{money(selected.priceCents)}</strong>{(selected.optionGroups||[]).map((g,gi)=><div className="publicOptions" key={gi}><div><b>{g.name||"Escolha uma opção"}</b><small>{g.required?"Obrigatório":"Opcional"}</small></div>{(g.options||[]).map((o,oi)=><label key={oi}><input type={(g.max||1)===1?"radio":"checkbox"} name={"g"+gi} checked={(choices[gi]||[]).includes(oi)} onChange={()=>toggleChoice(gi,oi,g)}/><span>{o.name}</span>{o.priceCents>0&&<em>+ {money(o.priceCents)}</em>}</label>)}</div>)}<button className="addCartButton" onClick={addCart}><Plus/> Adicionar ao carrinho</button></div></div>}</div>}

function Login(){const google=new GoogleAuthProvider();const[email,setEmail]=useState(""),[password,setPassword]=useState(""),[error,setError]=useState(""),[busy,setBusy]=useState(false);async function submit(e){e.preventDefault();setError("");setBusy(true);try{await signInWithEmailAndPassword(auth,email,password)}catch{setError("E-mail ou senha inválidos.")}finally{setBusy(false)}}return <div className="loginPage"><div className="loginBrand"><span>C</span><b>Comanda</b></div><form className="loginBox" onSubmit={submit}><small>GESTÃO DO RESTAURANTE</small><h1>Bem-vindo</h1><p>Entre para acompanhar pedidos, cozinha, mesas e vendas.</p><label>E-mail<div className="input"><Mail/><input type="email" value={email} onChange={e=>setEmail(e.target.value)} required/></div></label><label>Senha<div className="input"><Lock/><input type="password" value={password} onChange={e=>setPassword(e.target.value)} required/></div></label>{error&&<div className="loginError">{error}</div>}<button className="loginButton" disabled={busy}>{busy?"Entrando...":"Entrar no painel"}</button><div className="or"><span/>ou<span/></div><button type="button" className="googleButton" onClick={()=>signInWithPopup(auth,google).catch(()=>setError("Não foi possível entrar com Google."))}>G&nbsp;&nbsp; Entrar com Google</button><div className="loginFoot">Nova plataforma • Firebase conectado</div></form></div>}

function TenantGate({user}){const[state,setState]=useState({loading:true,restaurants:[],error:""});useEffect(()=>{(async()=>{try{const snap=await getDocs(collection(db,"userRestaurantAccess",user.uid,"restaurants"));const restaurants=snap.docs.map(d=>({restaurantId:d.id,...d.data()})).filter(x=>x.active===true);setState({loading:false,restaurants,error:""})}catch(e){setState({loading:false,restaurants:[],error:e.code||e.message})}})()},[user.uid]);if(state.loading)return <div className="loading">Localizando seu estabelecimento...</div>;if(!state.restaurants.length)return <NoRestaurant user={user} error={state.error}/>;return <Panel user={user} membership={state.restaurants[0]}/>}

function NoRestaurant({user,error}){const[name,setName]=useState(""),[type,setType]=useState("restaurant"),[phone,setPhone]=useState(""),[busy,setBusy]=useState(false),[msg,setMsg]=useState("");async function create(e){e.preventDefault();setBusy(true);setMsg("");try{const token=await user.getIdToken();const r=await fetch("/api/create-restaurant",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+token},body:JSON.stringify({name,type,phone})});const raw=await r.text();let data={};try{data=raw?JSON.parse(raw):{}}catch{data={error:"server_response",detail:raw}}if(!r.ok)throw new Error(data.error==="server_response"?(data.detail||"Erro do servidor."):data.error||"Não foi possível cadastrar.");location.reload()}catch(e){const m={invalid_name:"Informe um nome válido.",invalid_phone:"Informe um telefone/WhatsApp válido.",account_already_linked:"Esta conta já possui um estabelecimento.",internal_error:"Não foi possível concluir. Verifique a configuração do servidor."};setMsg(m[e.message]||e.message)}finally{setBusy(false)}}return <div className="onboardPage"><form className="onboardCard" onSubmit={create}><div className="onboardIcon"><Building2/></div><small>PRIMEIRO ACESSO</small><h1>Cadastre seu estabelecimento</h1><p>Esses dados criam o ambiente exclusivo da sua empresa. Depois você poderá configurar cardápio, pedidos, pagamentos e atendimento.</p><div className="userLine"><ShieldCheck/><div><b>{user.displayName||"Usuário autenticado"}</b><span>{user.email}</span></div></div>{error&&<div className="techNote">Firestore: {error}</div>}<div className="onboardFields"><label>Nome do estabelecimento<input value={name} onChange={e=>setName(e.target.value)} placeholder="Ex.: Restaurante do Geraldo" minLength="3" maxLength="100" required/></label><label>Tipo de negócio<select value={type} onChange={e=>setType(e.target.value)}><option value="restaurant">Restaurante</option><option value="pizzeria">Pizzaria</option><option value="snack_bar">Lanchonete</option><option value="marmitaria">Marmitaria</option><option value="bar">Bar</option><option value="bakery">Padaria</option><option value="other">Outro</option></select></label><label>WhatsApp / telefone<input value={phone} onChange={e=>setPhone(e.target.value)} placeholder="(19) 99999-9999" required/></label></div>{msg&&<div className="loginError">{msg}</div>}<button className="primaryWide" disabled={busy}>{busy?"Criando ambiente...":"Criar meu estabelecimento"}</button><button type="button" className="linkButton" onClick={()=>signOut(auth)}>Sair desta conta</button></form></div>}

function Panel({user,membership}){const[page,setPage]=useState("Início"),[open,setOpen]=useState(false);const name=membership.restaurantName||membership.name||"Meu estabelecimento";const go=p=>{setPage(p);setOpen(false)};return <div className="app"><Sidebar name={name} user={user} page={page} go={go} open={open} close={()=>setOpen(false)}/><main><header><button className="mobileMenu" onClick={()=>setOpen(true)} aria-label="Abrir menu"><Menu/></button><div className="headerTitle"><h1>{page}</h1><p>{name} • {membership.role==="owner"?"Proprietário":membership.role}</p></div><div className="status"><i/> Operação ativa</div></header>{page==="Início"?<Dashboard setPage={go} membership={membership}/>:page==="Configurações"?<SettingsPage membership={membership}/>:page==="Cardápio"?<MenuPage membership={membership}/>:page==="Pedidos"?<OrdersPage membership={membership}/>:page==="Cozinha"?<KitchenPage membership={membership}/>:page==="Delivery"?<DeliveryPage membership={membership}/>:<ModulePage page={page}/>}</main>{open&&<div className="scrim" onClick={()=>setOpen(false)}/>}</div>}

function Sidebar({name,user,page,go,open,close}){return <aside className={open?"open":""}><div className="brand"><span>C</span><div><b>Comanda</b><small>Gestão inteligente</small></div><button className="closeMenu" onClick={close}><X/></button></div><div className="restaurant"><Store/><div><small>Estabelecimento</small><b>{name}</b></div></div><nav>{groups.map(([group,items])=><div className="navGroup" key={group}><small>{group}</small>{items.map(([n,I])=><button key={n} className={page===n?"active":""} onClick={()=>go(n)}><I/>{n}</button>)}</div>)}</nav><div className="account"><small>{user.email}</small><button onClick={()=>signOut(auth)}><LogOut/> Sair</button></div></aside>}

function Dashboard({setPage,membership}){const[orders]=useOrders(membership.restaurantId);const today=new Date(),todayOrders=orders.filter(o=>{const d=o.createdAt?.toDate?.();return d&&d.getFullYear()===today.getFullYear()&&d.getMonth()===today.getMonth()&&d.getDate()===today.getDate()});const valid=todayOrders.filter(o=>o.status!=="CANCELLED"),revenue=valid.filter(o=>o.paymentStatus==="PAID"||["CASH","CARD_ON_DELIVERY"].includes(o.paymentMethod)&&o.status==="COMPLETED").reduce((n,o)=>n+Number(o.totalCents||0),0),ticket=valid.length?Math.round(valid.reduce((n,o)=>n+Number(o.totalCents||0),0)/valid.length):0,newCount=orders.filter(o=>["RECEIVED","ACCEPTED"].includes(o.status)).length,preparing=orders.filter(o=>o.status==="PREPARING").length,ready=orders.filter(o=>o.status==="READY").length;return <><section className="hero"><div><small>PAINEL DO ESTABELECIMENTO</small><h2>Sua operação em um só lugar</h2><p>Acompanhe pedidos, produção, atendimento e vendas.</p></div><button onClick={()=>setPage("Pedidos")}><ShoppingBag/> Ver pedidos</button></section><div className="stats"><Card t="Pedidos hoje" v={String(todayOrders.length)} s={todayOrders.length?"Atualizado em tempo real":"Nenhum pedido hoje"}/><Card t="Faturamento" v={moneyBR(revenue)} s="Concluído/recebido hoje"/><Card t="Ticket médio" v={moneyBR(ticket)} s="Pedidos válidos de hoje"/><Card t="Em preparo" v={String(preparing)} s="Agora"/></div><div className="homeGrid"><section className="panel"><div className="panelhead"><div><h3>Fluxo de pedidos</h3><p>Acompanhe a operação em tempo real</p></div><span className="miniLive"><i/> ao vivo</span></div><div className="flow"><button onClick={()=>setPage("Pedidos")}><b>{newCount}</b><span>Novos</span></button><ChevronRight/><button onClick={()=>setPage("Cozinha")}><b>{preparing}</b><span>Em preparo</span></button><ChevronRight/><button onClick={()=>setPage("Pedidos")}><b>{ready}</b><span>Prontos</span></button></div></section><section className="panel"><div className="panelhead"><div><h3>Atalhos</h3><p>Operação rápida</p></div></div><div className="quick"><button onClick={()=>setPage("Pedidos")}><ShoppingBag/>Pedidos</button><button onClick={()=>setPage("Cozinha")}><ChefHat/>Cozinha</button><button onClick={()=>setPage("Cardápio")}><Package/>Cardápio</button><button onClick={()=>setPage("Configurações")}><Settings/>Minha loja</button></div></section></div></>}
function Card({t,v,s}){return <div className="card"><span>{t}</span><b>{v}</b><small>{s}</small></div>}

const moduleCopy={
 "Pedidos":["Central de pedidos","Delivery, retirada, balcão e mesa serão acompanhados aqui."],
 "Cardápio":["Cardápio","Categorias, produtos, preços, adicionais, tamanhos e disponibilidade."],
 "Clientes":["Clientes","Histórico, contatos, endereços e relacionamento com seus clientes."],
 "Financeiro":["Financeiro","Vendas, recebimentos, PIX, taxas e relatórios."],
 "Cozinha":["Cozinha / KDS","Fila de produção para a equipe preparar e liberar os pedidos."],
 "Mesas e comandas":["Mesas e comandas","Atendimento presencial, comandas, consumo e fechamento de mesa."],
 "Delivery":["Delivery","Áreas de entrega, taxas, bairros, retirada e entregadores."],
 "Promoções":["Promoções","Cupons, descontos e campanhas do estabelecimento."],
 "Marketing":["Marketing","Banner, QR Code, link do cardápio e comunicação com clientes."]
};
function DeliveryPage({membership}){const[areas,setAreas]=useState([]),[ranges,setRanges]=useState([]),[config,setConfig]=useState({mode:"NEIGHBORHOOD",freeEnabled:false,freeType:"RADIUS",freeMaxKm:"3",freeMinimum:"",freeNeighborhood:""}),[form,setForm]=useState({neighborhood:"",fee:"",minimum:"",estimatedMinutes:"40"}),[rangeForm,setRangeForm]=useState({minKm:"0",maxKm:"5",fee:"5,00",minimum:"",estimatedMinutes:"40"}),[editing,setEditing]=useState(""),[bulkText,setBulkText]=useState(""),[bulkFee,setBulkFee]=useState(""),[bulkMinutes,setBulkMinutes]=useState("40"),[sheetPreview,setSheetPreview]=useState([]),[cityNeighborhoods,setCityNeighborhoods]=useState([]),[availableCities,setAvailableCities]=useState([]),[citiesLoading,setCitiesLoading]=useState(false),[selectedCity,setSelectedCity]=useState(""),[bairroSearch,setBairroSearch]=useState(""),[cityLoading,setCityLoading]=useState(false),[routeLoading,setRouteLoading]=useState(""),[routeResults,setRouteResults]=useState({}),[sheetLoading,setSheetLoading]=useState(false),[saving,setSaving]=useState(false),[error,setError]=useState("");const rid=membership.restaurantId,cents=v=>Math.round(Number(String(v||0).replace(",","."))*100);useEffect(()=>{const u1=onSnapshot(collection(db,"restaurants",rid,"deliveryAreas"),x=>setAreas(x.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>(a.neighborhood||"").localeCompare(b.neighborhood||""))),()=>setError("Não foi possível carregar as áreas."));const u2=onSnapshot(collection(db,"restaurants",rid,"deliveryRanges"),x=>setRanges(x.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>Number(a.minKm)-Number(b.minKm))));const u3=onSnapshot(doc(db,"restaurants",rid,"settings","delivery"),x=>{if(x.exists())setConfig(v=>({...v,...x.data(),freeMaxKm:String(x.data().freeMaxKm??v.freeMaxKm),freeMinimum:x.data().freeMinimumCents?String(x.data().freeMinimumCents/100).replace(".",","):""}))});return()=>{u1();u2();u3()}},[rid]);async function saveConfig(patch={}){const next={...config,...patch};setConfig(next);try{await setDoc(doc(db,"restaurants",rid,"settings","delivery"),{mode:next.mode,freeEnabled:!!next.freeEnabled,freeType:next.freeType,freeMaxKm:Number(next.freeMaxKm||0),freeMinimumCents:cents(next.freeMinimum),freeNeighborhood:next.freeNeighborhood||"",updatedAt:serverTimestamp()},{merge:true})}catch{setError("Não foi possível salvar a configuração.")}}async function saveArea(e){e.preventDefault();const neighborhood=form.neighborhood.trim(),fee=cents(form.fee),minimum=cents(form.minimum),estimatedMinutes=Math.max(1,Number(form.estimatedMinutes||40));if(neighborhood.length<2||!Number.isFinite(fee)||fee<0){setError("Confira bairro e taxa.");return}setSaving(true);try{const data={neighborhood,neighborhoodKey:neighborhood.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().trim(),feeCents:fee,minimumOrderCents:minimum,estimatedMinutes,active:true,updatedAt:serverTimestamp()};if(editing)await updateDoc(doc(db,"restaurants",rid,"deliveryAreas",editing),data);else await addDoc(collection(db,"restaurants",rid,"deliveryAreas"),{...data,createdAt:serverTimestamp()});setForm({neighborhood:"",fee:"",minimum:"",estimatedMinutes:"40"});setEditing("")}catch{setError("Não foi possível salvar o bairro.")}finally{setSaving(false)}}async function loadDeliveryCities(){setCitiesLoading(true);setError("");try{const r=await fetch("/api/delivery-sheet?action=listCities",{cache:"no-store"});const d=await r.json();if(!r.ok)throw new Error(d.error||"Falha ao carregar cidades.");setAvailableCities(d.cities||[]);if(!d.cities?.length)setError("Nenhuma aba de cidade encontrada. Confira a implantação do Apps Script.");setSelectedCity(previous=>previous&&d.cities?.some(x=>x.city+"|"+x.state===previous)?previous:d.cities?.length?d.cities[0].city+"|"+d.cities[0].state:"")}catch(e){setError(e.message||"Erro ao listar cidades.")}finally{setCitiesLoading(false)}}useEffect(()=>{loadDeliveryCities()},[rid]);async function fetchCityNeighborhoods(){setCityLoading(true);setError("");try{const snap=await getDoc(doc(db,"restaurants",rid,"settings","public"));const pub=snap.data()||{};let city=String(pub.city||"").trim(),state=String(pub.state||"").trim();if(selectedCity){const parts=selectedCity.split("|");city=parts[0];state=parts[1]||state}if(!city)throw new Error("Selecione uma cidade.");const r=await fetch("/api/delivery-sheet?action=getCityNeighborhoods&city="+encodeURIComponent(city)+"&state="+encodeURIComponent(state));const d=await r.json();if(!r.ok)throw new Error(d.error==="sheet_not_configured"?"Integração com Google Sheets não configurada.":d.error||"Erro ao buscar bairros.");const seen=new Set();const names=(d.neighborhoods||[]).map(x=>({name:String(x.neighborhood||x.bairro||x.name||"").trim(),cep:String(x.cep||x.CEP||x.cepInicial||"").trim(),cepInicial:String(x.cepInicial||x.cep||"").trim(),cepFinal:String(x.cepFinal||x.cep||"").trim()})).filter(x=>{const key=x.name.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();if(!x.name||seen.has(key))return false;seen.add(key);return true});setCityNeighborhoods(names);if(!names.length)setError("Nenhum bairro encontrado para "+city+". Confira a aba da cidade no Google Sheets e o Apps Script publicado.");}catch(e){setError(e.message||"Falha ao buscar bairros.");}finally{setCityLoading(false)}}async function fetchSheetTable(){setSheetLoading(true);setError("");try{const r=await fetch("/api/delivery-sheet?restaurantId="+encodeURIComponent(rid));const d=await r.json();if(!r.ok)throw new Error(d.error||"sheet_error");const rows=Array.isArray(d.neighborhoods)?d.neighborhoods:[];if(!rows.length){setError("A planilha deste estabelecimento ainda não possui bairros.");setSheetPreview([]);return}setSheetPreview(rows)}catch(e){setError(e.message==="sheet_not_configured"?"Integração com Google Sheets ainda não configurada no Vercel.":"Não foi possível buscar a tabela do Google Sheets.")}finally{setSheetLoading(false)}}async function importSheetTable(){if(!sheetPreview.length)return;setSaving(true);setError("");try{const existing=new Map(areas.map(a=>[(a.neighborhoodKey||a.neighborhood||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9 ]/g," ").replace(/\s+/g," ").trim(),a]));for(const row of sheetPreview){const neighborhood=String(row.neighborhood||row.bairro||"").trim();if(!neighborhood)continue;const neighborhoodKey=neighborhood.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9 ]/g," ").replace(/\s+/g," ").trim();const feeRaw=row.feeCents??row.fee??row.taxa;if(feeRaw===null||feeRaw===undefined||String(feeRaw).trim()==="")continue;const feeCents=row.feeCents!=null?Number(row.feeCents):Math.round(Number(String(feeRaw).replace(",","."))*100);if(!Number.isFinite(feeCents)||feeCents<0)continue;const data={neighborhood,neighborhoodKey,feeCents:Number.isFinite(feeCents)?feeCents:0,minimumOrderCents:Number(row.minimumOrderCents||0),estimatedMinutes:Math.max(1,Number(row.estimatedMinutes||row.tempoMin||40)),referenceDistanceKm:Number(row.distanceKm||row.distanciaKm||0)||null,active:row.active!==false,source:"GOOGLE_SHEETS",updatedAt:serverTimestamp()};const old=existing.get(neighborhoodKey);if(old)continue;else await addDoc(collection(db,"restaurants",rid,"deliveryAreas"),{...data,createdAt:serverTimestamp()})}setSheetPreview([])}catch{setError("Não foi possível importar a tabela para o estabelecimento.")}finally{setSaving(false)}}async function addNeighborhoodsBulk(){const names=[...new Set(bulkText.split(/\n|;/).map(x=>x.trim()).filter(x=>x.length>1))];if(!names.length){setError("Cole ou digite os bairros, um por linha.");return}const existing=new Set(areas.map(a=>(a.neighborhoodKey||a.neighborhood||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9 ]/g," ").replace(/\s+/g," ").trim()));const fee=cents(bulkFee),estimatedMinutes=Math.max(1,Number(bulkMinutes||40));if(!Number.isFinite(fee)||fee<0){setError("Confira a taxa padrão.");return}setSaving(true);setError("");try{let added=0;for(const neighborhood of names){const neighborhoodKey=neighborhood.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9 ]/g," ").replace(/\s+/g," ").trim();if(existing.has(neighborhoodKey))continue;await addDoc(collection(db,"restaurants",rid,"deliveryAreas"),{neighborhood,neighborhoodKey,feeCents:fee,minimumOrderCents:0,estimatedMinutes,active:true,createdAt:serverTimestamp(),updatedAt:serverTimestamp()});existing.add(neighborhoodKey);added++}setBulkText("");if(!added)setError("Todos esses bairros já estavam cadastrados.")}catch{setError("Não foi possível importar todos os bairros.")}finally{setSaving(false)}}async function saveRange(e){e.preventDefault();const minKm=Number(String(rangeForm.minKm).replace(",",".")),maxKm=Number(String(rangeForm.maxKm).replace(",",".")),fee=cents(rangeForm.fee);if(!Number.isFinite(minKm)||!Number.isFinite(maxKm)||maxKm<=minKm||fee<0){setError("Confira a faixa de distância.");return}try{await addDoc(collection(db,"restaurants",rid,"deliveryRanges"),{minKm,maxKm,feeCents:fee,minimumOrderCents:cents(rangeForm.minimum),estimatedMinutes:Number(rangeForm.estimatedMinutes||40),active:true,createdAt:serverTimestamp(),updatedAt:serverTimestamp()});setRangeForm({minKm:String(maxKm),maxKm:String(maxKm+2),fee:"",minimum:"",estimatedMinutes:"40"})}catch{setError("Não foi possível adicionar a faixa.")}}async function toggle(col,a){try{await updateDoc(doc(db,"restaurants",rid,col,a.id),{active:a.active===false,updatedAt:serverTimestamp()})}catch{setError("Não foi possível alterar.")}}return <section className="deliveryPage"><div className="ordersTop"><div><small>DELIVERY</small><h2>Taxas de entrega</h2><p>Cadastre os bairros atendidos e defina o valor de entrega de cada um.</p></div><div className="deliveryCount">Recomendado: por bairro</div></div><section className="panel deliveryMode"><div className="panelhead"><div><h3>Como cobrar a entrega?</h3><p>Por bairro é o modo recomendado: o CEP identifica o bairro e o sistema aplica a taxa cadastrada.</p></div></div><div className="modeCards"><button className={config.mode==="NEIGHBORHOOD"?"active":""} onClick={()=>saveConfig({mode:"NEIGHBORHOOD"})}><Building2/><b>Por bairro — recomendado</b><span>O CEP identifica o bairro e aplica o valor cadastrado.</span></button><button className={config.mode==="DISTANCE"?"active":""} onClick={()=>saveConfig({mode:"DISTANCE"})}><MapPin/><b>Por distância — opcional</b><span>Taxa conforme os quilômetros da rota.</span></button></div></section>{config.mode==="DISTANCE"?<div className="deliveryLayout"><form className="deliveryForm panel" onSubmit={saveRange}><div className="panelhead"><div><h3>Nova faixa</h3><p>Ex.: de 5 km até 7 km.</p></div></div><div className="deliveryFormGrid"><label>De (km)<input value={rangeForm.minKm} onChange={e=>setRangeForm({...rangeForm,minKm:e.target.value})}/></label><label>Até (km)<input value={rangeForm.maxKm} onChange={e=>setRangeForm({...rangeForm,maxKm:e.target.value})}/></label><label>Taxa<input value={rangeForm.fee} onChange={e=>setRangeForm({...rangeForm,fee:e.target.value})} placeholder="7,00"/></label><label>Pedido mínimo<input value={rangeForm.minimum} onChange={e=>setRangeForm({...rangeForm,minimum:e.target.value})} placeholder="25,00"/></label></div><label>Previsão (minutos)<input type="number" value={rangeForm.estimatedMinutes} onChange={e=>setRangeForm({...rangeForm,estimatedMinutes:e.target.value})}/></label><button className="saveDelivery">Adicionar faixa</button></form><section className="panel deliveryAreas"><div className="panelhead"><div><h3>Faixas de distância</h3><p>A distância será calculada pela rota.</p></div></div><div className="deliveryAreaList">{ranges.map(a=><article className={a.active===false?"disabled":""} key={a.id}><div className="deliveryAreaMain"><MapPin/><div><b>{a.minKm} a {a.maxKm} km</b><small>{a.estimatedMinutes||40} min • mínimo {moneyBR(a.minimumOrderCents)}</small></div></div><strong>{moneyBR(a.feeCents)}</strong><div className="deliveryAreaActions"><button onClick={()=>toggle("deliveryRanges",a)}>{a.active===false?"Ativar":"Pausar"}</button></div></article>)}</div></section></div>:<div className="deliveryLayout"><div><section className="deliveryForm panel sheetImport"><div className="panelhead"><div><h3>Buscar bairros da cidade</h3><p>Base compartilhada por cidade, bairro e CEP.</p></div></div><button type="button" onClick={loadDeliveryCities}>{citiesLoading?"Carregando cidades...":"Atualizar cidades • TESTE DEPLOY 20/10"}</button><label>Cidade de atendimento<select value={selectedCity} onChange={e=>{setSelectedCity(e.target.value);setCityNeighborhoods([]);setRouteResults({})}}><option value="">Selecione a cidade</option>{availableCities.map(c=><option key={c.city+"|"+c.state} value={c.city+"|"+c.state}>{c.city} - {c.state}</option>)}</select></label><label>Buscar bairro ou CEP<input value={bairroSearch} onChange={e=>setBairroSearch(e.target.value)} placeholder="Ex.: Ajapi ou 13508-000"/></label><button type="button" className="saveDelivery" disabled={cityLoading||saving} onClick={fetchCityNeighborhoods}>{cityLoading?"Buscando bairros...":"Buscar bairros"}</button>{cityNeighborhoods.length>0&&<><div className="sheetPreview"><b>{cityNeighborhoods.length} bairros encontrados</b>{cityNeighborhoods.filter(item=>(item.name+" "+item.cep).toLowerCase().includes(bairroSearch.toLowerCase())).map((item,i)=><span key={i}>{item.name} • CEP: {item.cepInicial===item.cepFinal?item.cepInicial:item.cepInicial+" a "+item.cepFinal} </span>)}</div><button type="button" className="saveDelivery" onClick={()=>setBulkText(cityNeighborhoods.filter(x=>(x.name+" "+x.cep).toLowerCase().includes(bairroSearch.toLowerCase())).map(x=>x.name).join("\n"))}>Usar lista no cadastro em lote</button><small>Revise a taxa padrão antes de adicionar. Bairros já cadastrados serão ignorados.</small></>}</section><section className="deliveryForm panel"><div className="panelhead"><div><h3>Adicionar vários bairros</h3><p>Cole uma lista com um bairro por linha. A taxa e o prazo abaixo serão aplicados inicialmente a todos.</p></div></div><label>Lista de bairros<textarea rows="8" value={bulkText} onChange={e=>setBulkText(e.target.value)} placeholder={"Centro\nJardim São Caetano II\nAlto do Santana\nAjapi"}/></label><div className="deliveryFormGrid"><label>Taxa padrão<input value={bulkFee} onChange={e=>setBulkFee(e.target.value)} placeholder="Ex.: 5,00"/></label><label>Previsão padrão (min)<input type="number" value={bulkMinutes} onChange={e=>setBulkMinutes(e.target.value)}/></label></div><button type="button" className="saveDelivery" disabled={saving} onClick={addNeighborhoodsBulk}>{saving?"Adicionando...":"Adicionar lista de bairros"}</button><small>Bairros que já existem serão ignorados para evitar duplicidade.</small></section><form className="deliveryForm panel" onSubmit={saveArea}><div className="panelhead"><div><h3>{editing?"Editar bairro":"Adicionar bairro"}</h3><p>O nome deve corresponder ao bairro retornado pelo CEP. Depois vamos preencher essa lista automaticamente.</p></div></div><label>Bairro<input value={form.neighborhood} onChange={e=>setForm({...form,neighborhood:e.target.value})} required/></label><div className="deliveryFormGrid"><label>Taxa<input value={form.fee} onChange={e=>setForm({...form,fee:e.target.value})}/></label><label>Pedido mínimo<input value={form.minimum} onChange={e=>setForm({...form,minimum:e.target.value})}/></label></div><label>Previsão (minutos)<input type="number" value={form.estimatedMinutes} onChange={e=>setForm({...form,estimatedMinutes:e.target.value})}/></label><button className="saveDelivery" disabled={saving}>{editing?"Salvar":"Adicionar bairro"}</button></form></div><section className="panel deliveryAreas"><div className="panelhead"><div><h3>Tabela de bairros e taxas</h3><p>No pedido: CEP → bairro → taxa desta tabela.</p></div></div><div className="deliveryAreaList">{areas.map(a=><article className={a.active===false?"disabled":""} key={a.id}><div className="deliveryAreaMain"><MapPin/><div><b>{a.neighborhood}</b><small>{a.estimatedMinutes||40} min • mínimo {moneyBR(a.minimumOrderCents)}</small></div></div><strong>{moneyBR(a.feeCents)}</strong><div className="deliveryAreaActions"><button onClick={()=>{setEditing(a.id);setForm({neighborhood:a.neighborhood,fee:String(a.feeCents/100).replace(".",","),minimum:String((a.minimumOrderCents||0)/100).replace(".",","),estimatedMinutes:String(a.estimatedMinutes||40)})}}><Pencil/> Editar</button><button onClick={()=>toggle("deliveryAreas",a)}>{a.active===false?"Ativar":"Pausar"}</button></div></article>)}</div></section></div>}<section className="panel freeShipping"><div className="freeHead"><div><Tag/><div><h3>Frete grátis promocional</h3><p>Use para conquistar ou recuperar clientes de uma região.</p></div></div><label className="switchLine"><input type="checkbox" checked={!!config.freeEnabled} onChange={e=>saveConfig({freeEnabled:e.target.checked})}/> Ativar</label></div>{config.freeEnabled&&<div className="freeGrid"><label>Aplicar por<select value={config.freeType} onChange={e=>saveConfig({freeType:e.target.value})}><option value="RADIUS">Raio / distância</option><option value="NEIGHBORHOOD">Bairro específico</option></select></label>{config.freeType==="RADIUS"?<label>Até quantos km?<input value={config.freeMaxKm} onChange={e=>setConfig({...config,freeMaxKm:e.target.value})} onBlur={()=>saveConfig()}/></label>:<label>Bairro<input value={config.freeNeighborhood} onChange={e=>setConfig({...config,freeNeighborhood:e.target.value})} onBlur={()=>saveConfig()}/></label>}<label>Pedido mínimo para ganhar frete<input value={config.freeMinimum} onChange={e=>setConfig({...config,freeMinimum:e.target.value})} onBlur={()=>saveConfig()} placeholder="Ex.: 40,00"/></label></div>}<div className="promoExample">A taxa normal continuará registrada no pedido, mesmo quando o cliente pagar R$ 0,00 de entrega.</div></section>{error&&<div className="formError deliveryError">{error}</div>}<div className="deliveryRoadmap"><Truck/><div><b>Preparado para o app do entregador</b><span>Endereço confirmado, coordenadas, distância e taxa poderão acompanhar cada pedido.</span></div></div></section>}

function ModulePage({page}){const[t,d]=moduleCopy[page]||[page,"Módulo da nova plataforma."];return <section className="panel big"><div className="moduleIntro"><div className="moduleIcon"><Store/></div><div><small>MÓDULO</small><h2>{t}</h2><p>{d}</p></div></div><div className="coming"><span>Estrutura preparada</span><p>Os dados deste módulo serão isolados por estabelecimento.</p></div></section>}

const statusLabels={PENDING_PAYMENT:"Aguardando pagamento",RECEIVED:"Recebido",ACCEPTED:"Aceito",PREPARING:"Em preparo",READY:"Pronto",OUT_FOR_DELIVERY:"Saiu para entrega",COMPLETED:"Concluído",CANCELLED:"Cancelado"};
