function useOrders(restaurantId){const[orders,setOrders]=useState([]),[error,setError]=useState("");useEffect(()=>{const q=query(collection(db,"restaurants",restaurantId,"orders"),orderBy("createdAt","desc"));return onSnapshot(q,s=>{setOrders(s.docs.map(d=>({id:d.id,...d.data()})));setError("")},()=>setError("Não foi possível carregar os pedidos."))},[restaurantId]);return[orders,error]}
function OrderItems({order}){return <div className="orderItems">{(order.items||[]).map((item,i)=><div className="orderItem" key={i}><div><b>{item.qty}x {item.name}</b>{(item.options||[]).map((o,j)=><small key={j}>{o.group}: {o.name}</small>)}</div><strong>{moneyBR(item.totalCents)}</strong></div>)}</div>}
const moneyBR=v=>(Number(v||0)/100).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});
async function changeOrderStatus(restaurantId,orderId,status){const token=await auth.currentUser.getIdToken();const r=await fetch("/api/update-order-status",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+token},body:JSON.stringify({restaurantId,orderId,status})});const data=await r.json();if(!r.ok)throw new Error(data.error||"status_error");return data}
function OrdersPage({membership}){const[orders,error]=useOrders(membership.restaurantId),[filter,setFilter]=useState("OPEN"),[busy,setBusy]=useState("");const shown=orders.filter(o=>filter==="ALL"||filter==="OPEN"?!["COMPLETED","CANCELLED"].includes(o.status):o.status===filter);async function move(o,status){setBusy(o.id);try{await changeOrderStatus(membership.restaurantId,o.id,status)}catch{alert("Não foi possível atualizar o pedido.")}finally{setBusy("")}}return <section className="ordersPage"><div className="ordersTop"><div><small>PEDIDOS EM TEMPO REAL</small><h2>Central de pedidos</h2><p>Pedidos do cardápio público aparecem aqui automaticamente.</p></div><div className="liveBadge"><i/> Ao vivo</div></div><div className="orderFilters">{[["OPEN","Em aberto"],["PENDING_PAYMENT","Aguardando PIX"],["PREPARING","Em preparo"],["READY","Prontos"],["ALL","Todos"]].map(([v,l])=><button key={v} className={filter===v?"active":""} onClick={()=>setFilter(v)}>{l}</button>)}</div>{error&&<div className="techNote">{error}</div>}<div className="ordersList">{!shown.length?<div className="ordersEmpty"><ShoppingBag/><b>Nenhum pedido nesta etapa</b><span>Os novos pedidos aparecerão automaticamente.</span></div>:shown.map(o=><article className="orderCard" key={o.id}><header><div><span className="orderNumber">#{o.number}</span><b>{o.customerSnapshot?.name||"Cliente"}</b><small>{channelLabels[o.channel]||o.channel}{o.table?` • ${o.table}`:""}</small></div><span className={"orderStatus status-"+String(o.status).toLowerCase()}>{statusLabels[o.status]||o.status}</span></header><OrderItems order={o}/><div className="orderMeta"><span>{paymentLabels[o.paymentMethod]||o.paymentMethod}</span><strong>{moneyBR(o.totalCents)}</strong></div><div className="orderActions">{o.status==="RECEIVED"&&<button disabled={busy===o.id} onClick={()=>move(o,"ACCEPTED")}>Aceitar pedido</button>}{o.status==="ACCEPTED"&&<button disabled={busy===o.id} onClick={()=>move(o,"PREPARING")}>Enviar para cozinha</button>}{o.status==="PREPARING"&&<button disabled={busy===o.id} onClick={()=>move(o,"READY")}>Marcar pronto</button>}{o.status==="READY"&&o.channel==="DELIVERY"&&<button disabled={busy===o.id} onClick={()=>move(o,"OUT_FOR_DELIVERY")}>Saiu para entrega</button>}{o.status==="READY"&&o.channel!=="DELIVERY"&&<button disabled={busy===o.id} onClick={()=>move(o,"COMPLETED")}>Concluir</button>}{o.status==="OUT_FOR_DELIVERY"&&<button disabled={busy===o.id} onClick={()=>move(o,"COMPLETED")}>Concluir entrega</button>}{!["COMPLETED","CANCELLED"].includes(o.status)&&<button className="cancelOrder" disabled={busy===o.id} onClick={()=>move(o,"CANCELLED")}>Cancelar</button>}</div></article>)}</div></section>}
